import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"兌","description":"東坡易傳 - 兌","frontmatter":{"title":"兌","description":"東坡易傳 - 兌"},"headers":[],"relativePath":"classics/dongpo/059.md","filePath":"classics/dongpo/059.md"}'),o={name:"classics/dongpo/059.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><p>“兌”，亨，利貞。</p><p>《彖》曰：“兌”，說也。剛中而柔外，說以利貞。是以順乎天而應乎人。說以先民，民忘其勞；說以犯難，民忘其死；說之大，民勸矣哉！</p><p>小惠不足以勸民。</p><p>象曰：麗澤，“兌”；君子以朋友講習。</p><p>取其“樂而不流”者也。</p><p>初九：和兌，吉。象曰：“和兌”之“吉”，行未疑也。</p><p>九二：孚兌，吉；悔亡。象曰：“孚兌”之吉，信志也。</p><p>和而不同，謂之“和兌”；信於其類，謂之“孚兌”。六三小人，而初九、九二君子也；君子之說於小人，將以有所濟，非以為利也。初九以遠之，而無嫌至九二，則初九疑之矣，故必有以自信於初九者，而後“悔亡”。文予而實不予，所以信於初九也。</p><p>六三：來兌，兇。象曰：“來兌”之“兇”，位不當也。</p><p>九四：商兌，未寧；介疾，有喜。象曰：九四之“喜”，有慶也。</p><p>九五，“兌”之主也；上有上六，下有六三，皆其疾也。《傳》曰：“美疢不如惡石”。九四介於其間，以剛輔五，而議二陰者也，故曰：“商兌，未寧；介疾，有喜。”言疾去而後有喜也，疾去而後有喜，則《易》之所謂“慶”也。</p><p>九五：孚於剝，有厲。象曰：“孚於剝”，位正當也。</p><p>上六：引兌。象曰：“上六引兌”，未光也。</p><p>六三、上六，皆“兌”之小人，以陰為質，以說為事者，均也。六三履非其位，而處於二陽之間，以求說為兌者，故曰“來兌”，言初與二不招而自來也，其心易知，其為害淺，故二陽皆“吉”，而六三“兇”。上六超然於外，不累於物，此小人之託於無求以為“兌”者也，故曰“引兌”，言九五引之而後至也，其心難知，其為害深。故九五“孚於剝”，“剝”者，五陰而消一陽也。上六之害，何至於此？曰：九五以正當之位，而孚於難知之小人，其至於“剝”，豈足怪哉！雖然，其心蓋不知而賢之，非說其小人之實也，使知其實，則去之矣。故有“厲”而不兇。然則上六之所以不光，何也？曰：難進者，君子之事也；使上六引而不兌，則其道光矣。</p>',15)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
